package main

import "net/http"

func applicationStyleHandler(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/css; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	_, _ = w.Write([]byte(applicationStyle))
}

const applicationStyle = `
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;--bg:#080d18;--surface:#111827;--surface-2:#172033;--line:#293449;--text:#eef2ff;--muted:#94a3b8;--accent:#3b82f6;--accent-strong:#2563eb;--success:#34d399;--danger:#f87171}
*{scrollbar-color:#475569 transparent}
body{margin:0!important;max-width:none!important;padding:0!important;background:radial-gradient(circle at 15% -10%,rgb(37 99 235 / 18%),transparent 34rem),var(--bg)!important;color:var(--text)!important;line-height:1.5}
.app-shell{display:grid;grid-template-columns:248px minmax(0,1fr);min-height:100vh}
.app-sidebar{position:sticky;top:0;display:flex;flex-direction:column;gap:14px;height:100vh;padding:20px 14px;border-right:1px solid rgb(71 85 105 / 55%);background:rgb(15 23 42 / 92%);overflow-y:auto}
.app-main{padding:28px 28px 56px;max-width:1200px}
.main-nav{display:flex!important;flex-direction:column!important;align-items:stretch!important;gap:4px!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;backdrop-filter:none;position:static}
.main-nav .brand{display:flex;align-items:center;gap:7px;margin:0 0 10px!important;color:#fff!important;font-size:1.02rem;font-weight:750!important;letter-spacing:-.01em!important}.main-nav .brand:before{content:"";width:10px;height:10px;border-radius:50%;background:var(--accent);box-shadow:0 0 18px var(--accent)}.main-nav .brand small{padding:2px 7px;border:1px solid #334155;border-radius:999px;color:#bfdbfe;font-size:.68rem;font-weight:650}
.main-nav>a{padding:10px 12px!important;border:1px solid transparent;border-radius:10px!important;color:#b8c3d6!important;font-size:.9rem;font-weight:600;text-decoration:none;transition:background .15s,border-color .15s,color .15s}.main-nav>a:hover{border-color:#334155;background:#1e293b!important;color:#fff!important;transform:none}.main-nav>a.active{border-color:rgb(96 165 250 / 38%);background:linear-gradient(135deg,#2563eb,#1d4ed8)!important;color:#fff!important;box-shadow:0 6px 16px rgb(37 99 235 / 24%)}
#internet-status{display:block;margin:0 0 6px;padding:7px 10px;border:1px solid #334155;border-radius:10px;background:#0f172a;font-size:.78rem;font-weight:650;line-height:1.35;white-space:normal}
#network-info{display:flex!important;align-items:flex-start;flex-direction:column;gap:10px!important;margin:0!important;padding:10px 12px;border:1px solid rgb(51 65 85 / 72%);border-radius:12px;background:rgb(15 23 42 / 58%);color:var(--muted)!important;font-size:.82rem!important}#network-addresses{display:block;min-width:0;line-height:1.45;white-space:normal}#update-app-state{color:#bfdbfe}
.page-heading{display:flex!important;align-items:center!important;justify-content:space-between!important;flex-wrap:nowrap!important;gap:12px!important;margin:0 0 20px!important;width:100%;box-sizing:border-box}.page-heading h1{flex:0 1 auto!important;margin:0!important;white-space:nowrap}.page-heading button{flex:0 0 auto!important;margin-left:auto!important;width:auto!important;min-width:0!important;white-space:nowrap}
h1{margin:0 0 20px!important;color:#f8fafc;font-size:clamp(1.65rem,3vw,2.35rem);line-height:1.15;letter-spacing:-.035em}h2{letter-spacing:-.02em}p{color:#cbd5e1}.hint{color:var(--muted)!important}
table{width:100%;overflow:hidden;border:1px solid var(--line);border-collapse:separate!important;border-spacing:0!important;border-radius:14px;background:rgb(17 24 39 / 88%)!important;box-shadow:0 16px 44px rgb(0 0 0 / 18%)}th,td{padding:13px 14px!important;border-bottom:1px solid var(--line)!important;text-align:left}th{background:#151f31;color:#9fc5ff!important;font-size:.74rem;font-weight:750;letter-spacing:.055em;text-transform:uppercase}tbody tr:last-child td{border-bottom:0!important}tbody tr{transition:background .15s}tbody tr:hover{background:#18243a!important}td{color:#dbe4f0}td small{color:var(--muted)}code{color:#86efac!important;font-family:"Cascadia Code","SFMono-Regular",Consolas,monospace;font-size:.88em}
button,input,select{box-sizing:border-box;min-height:40px;padding:9px 13px;border:1px solid #3b485f;border-radius:9px!important;font:inherit}button{border-color:#3b82f6!important;background:linear-gradient(135deg,#3b82f6,#2563eb)!important;color:#fff!important;cursor:pointer;font-weight:650;box-shadow:0 5px 14px rgb(37 99 235 / 18%)!important;transition:transform .15s,filter .15s,border-color .15s}button:hover:not(:disabled){filter:brightness(1.1);transform:translateY(-1px)}button:active:not(:disabled){transform:translateY(0)}button:disabled{cursor:not-allowed;opacity:.55;box-shadow:none!important}input,select{background:#0b1220!important;color:#f8fafc!important;outline:none;transition:border-color .15s,box-shadow .15s}input:hover,select:hover{border-color:#64748b}input:focus,select:focus{border-color:#60a5fa;box-shadow:0 0 0 3px rgb(59 130 246 / 20%)}input[readonly]{background:#111827!important;color:#9fb0c7!important}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid rgb(96 165 250 / 62%)!important;outline-offset:2px}label{color:#c9d8ec!important;font-size:.86rem;font-weight:650}
dialog{padding:26px!important;border:1px solid #46546b!important;border-radius:16px!important;background:linear-gradient(145deg,#182236,#111827)!important;color:var(--text)!important;box-shadow:0 30px 90px rgb(0 0 0 / 58%)}dialog::backdrop{background:rgb(2 6 23 / 78%)!important;backdrop-filter:blur(4px)}dialog h2,dialog h3{margin-top:0}.actions{display:flex;justify-content:flex-end;gap:9px;margin-top:24px!important}.actions button{min-width:96px}.actions button:not(:last-child):not(.danger){border-color:#475569;background:#253147;box-shadow:none}.danger,.leave{border-color:#b91c1c!important;background:linear-gradient(135deg,#dc2626,#991b1b)!important;box-shadow:0 5px 14px rgb(185 28 28 / 18%)}
.empty,.setup,.error-box,.node-card{border:1px solid var(--line)!important;border-radius:14px!important;background:linear-gradient(145deg,rgb(23 32 51 / 92%),rgb(15 23 42 / 92%))!important;box-shadow:0 14px 38px rgb(0 0 0 / 16%)}.empty,.setup,.error-box{padding:22px!important}.node-card{padding:20px!important}.status-dot{box-shadow:0 0 0 4px rgb(255 255 255 / 5%),0 0 18px currentColor!important}.status-dot.online,.network-status.ok{color:var(--success);background:var(--success)!important}.status-dot.offline,.network-status.error{color:var(--danger);background:var(--danger)!important}
.toggle,.media-toggle-label input[type="checkbox"]{box-sizing:border-box!important;width:44px!important;min-width:44px!important;max-width:44px!important;height:24px!important;min-height:24px!important;max-height:24px!important;flex:0 0 44px!important;padding:0!important;border:0!important;border-radius:999px!important;background:#4b5563!important;box-shadow:none!important}.toggle[aria-checked="true"],.media-toggle-label input[type="checkbox"]:checked{background:#2563eb!important}.camera-link,.copy-path{border-color:#475569!important;background:#1e293b!important;color:#bfdbfe!important;box-shadow:none!important}.info-button{width:22px!important;min-width:22px;height:22px!important;min-height:22px!important;padding:0!important;border:1px solid #64748b!important;border-radius:50%!important;background:#1e293b!important;color:#bfdbfe!important;line-height:20px!important;box-shadow:none!important}.notice{position:fixed;right:24px;bottom:24px;z-index:10;min-width:310px;padding:14px 18px;border:1px solid #3b82f6;border-radius:14px;background:#172a47;color:#dbeafe;line-height:1.5}.notice[hidden]{display:none}.discovery-title{font-weight:700;margin-bottom:7px}.discovery-step{display:flex;justify-content:space-between;gap:22px}.step-running{color:#fde68a}.step-complete{color:#86efac}.step-error{color:#fca5a5}
.camera-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:16px;margin-top:4px}.camera-card{display:flex;flex-direction:column;gap:8px;padding:12px 14px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(145deg,rgb(23 32 51 / 94%),rgb(15 23 42 / 94%));box-shadow:0 14px 38px rgb(0 0 0 / 16%);cursor:pointer;transition:border-color .15s,background .15s}.camera-card:hover{border-color:rgb(59 130 246 / 45%);background:linear-gradient(145deg,rgb(24 36 58 / 96%),rgb(15 23 42 / 96%))}.camera-card-header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.camera-card-title{display:flex;flex-direction:column;gap:4px;min-width:0}.camera-card-meta{display:flex;flex-wrap:nowrap;gap:8px;align-items:center;min-width:0;overflow:hidden}.camera-card-controls{display:flex;align-items:center;gap:10px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end}.camera-card-label{color:var(--muted);font-size:.74rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;white-space:nowrap}.mediamtx-badge{display:inline-flex;align-items:center;padding:5px 10px;border-radius:999px;font-size:.72rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;white-space:nowrap;line-height:1;color:#bfdbfe;background:rgb(37 99 235 / 18%);border:1px solid rgb(59 130 246 / 35%)}.mediamtx-badge.enabled{color:#dbeafe;background:rgb(37 99 235 / 28%);border:1px solid rgb(96 165 250 / 45%)}.mediamtx-badge.disabled{color:#93c5fd;background:rgb(37 99 235 / 12%);border:1px solid rgb(59 130 246 / 22%);opacity:.78}.stream-rtsp-panel{display:flex;flex-direction:column;gap:6px}.rtsp-line{display:flex;align-items:center;gap:8px;min-width:0}.rtsp-line .camera-path{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source-display{display:inline-flex;align-items:center;gap:8px;min-width:0;max-width:100%}.source-icon{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;flex:0 0 24px;border:1px solid rgb(71 85 105 / 55%);border-radius:6px;font-size:14px;background:rgb(15 23 42 / 72%)}.source-detail{color:var(--muted);font-size:.78rem}.stream-badge{display:inline-flex;align-items:center;padding:5px 10px;border-radius:999px;font-size:.72rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;white-space:nowrap;line-height:1;color:#bfdbfe;background:rgb(37 99 235 / 18%);border:1px solid rgb(59 130 246 / 35%)}.stream-badge.transcode{color:#86efac;background:rgb(6 78 59 / 22%);border:1px solid rgb(52 211 153 / 35%)}.stream-badge.unknown{color:#94a3b8;background:rgb(51 65 85 / 22%);border:1px solid rgb(71 85 105 / 45%)}.copy-path{width:auto!important;min-height:34px!important;padding:6px 10px!important;box-shadow:none!important}.camera-card-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:14px}.camera-card .stream-details-panel{margin:0;padding:0;border:0;border-radius:0;background:transparent;gap:6px 10px}.camera-card .stream-chip{display:grid;grid-template-columns:auto minmax(0,1fr) auto;width:100%;align-items:center;gap:8px;padding:0;border:0;border-radius:0;background:transparent}.camera-card .stream-chip .preview-button{justify-self:end}.stream-details-panel{display:flex;align-items:center;flex-wrap:wrap;gap:10px 14px;padding:12px 14px;border:1px solid rgb(71 85 105 / 55%);border-radius:12px;background:linear-gradient(145deg,rgb(15 23 42 / 92%),rgb(23 32 51 / 72%))}.stream-chip{display:inline-flex;align-items:center;flex-wrap:wrap;gap:8px;padding:7px 10px;border:1px solid rgb(71 85 105 / 45%);border-radius:10px;background:rgb(15 23 42 / 72%);color:#cbd5e1;font-size:.82rem;line-height:1.35}.stream-chip strong{color:#93c5fd;font-size:.74rem;font-weight:750;letter-spacing:.04em;text-transform:uppercase}.camera-name{display:block;color:#f8fafc;font-weight:700;line-height:1.3}.camera-name.muted{color:var(--muted);font-weight:600}.camera-meta{display:block;margin-top:3px;color:var(--muted);font-size:.82rem}.camera-path{display:inline-block;padding:3px 8px;border:1px solid rgb(52 211 153 / 28%);border-radius:8px;background:rgb(6 78 59 / 18%);color:#86efac!important;font-size:.84rem}.camera-address{color:#bfdbfe;font-variant-numeric:tabular-nums}.camera-vendor{display:inline-block;flex:0 0 auto;padding:2px 8px;border-radius:999px;background:rgb(37 99 235 / 14%);color:#bfdbfe;font-size:.78rem;font-weight:650;white-space:nowrap}.camera-model{min-width:0;overflow:hidden;color:#dbe4f0;font-size:.88rem;white-space:nowrap;text-overflow:ellipsis}.col-toggle,.col-status,.col-actions{text-align:center;white-space:nowrap;vertical-align:middle!important}.status-pill{display:inline-flex;align-items:center;gap:7px;padding:5px 10px;border-radius:999px;font-size:.78rem;font-weight:650;line-height:1}.status-pill.online{color:#86efac;background:rgb(6 78 59 / 22%);border:1px solid rgb(52 211 153 / 35%)}.status-pill.offline{color:#fca5a5;background:rgb(127 29 29 / 18%);border:1px solid rgb(248 113 113 / 28%)}.status-pill .status-dot{width:8px;height:8px;min-width:8px;box-shadow:none!important}.btn-danger-sm,.btn-secondary-sm{width:auto!important;min-height:34px!important;padding:6px 12px!important;font-size:.82rem!important;line-height:1.2!important;box-shadow:none!important}.btn-secondary-sm{border-color:#475569!important;background:#1e293b!important;color:#bfdbfe!important}.btn-danger-sm.danger{padding:6px 12px!important}.init-badge{display:inline-flex;align-items:center;min-height:34px;padding:6px 12px;border:1px solid #475569;border-radius:999px;background:#1e293b;color:#cbd5e1;font-size:.82rem;line-height:1.2;white-space:nowrap}.init-badge.ready{border-color:rgb(52 211 153 / 35%);color:#86efac}.init-badge.pending{border-color:rgb(251 191 36 / 35%);color:#fde68a}.camera-device-info{margin:-8px 0 18px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.camera-name-row,.network-fields,.credentials-fields{display:flex;align-items:flex-end;gap:18px}.camera-name-field,.network-field,.credential-field{flex:1}.media-toggle-label{display:flex;align-items:flex-start;flex-direction:column;gap:5px;margin:0 0 5px;white-space:nowrap}.preview-dialog{width:min(960px,calc(100% - 40px))}.preview-header{display:flex;align-items:center;justify-content:space-between;gap:16px}.preview-header h2{margin:0}.preview-metadata{margin:12px 0 0;padding:9px 12px;border:1px solid #374151;border-radius:10px;background:#111827;color:#cbd5e1}.preview-metadata p{margin:3px 0}.preview-frame{display:block;width:100%;aspect-ratio:16/9;margin-top:12px;border:0;border-radius:10px;background:#000}.preview-status{min-height:1.5em;margin:10px 0 0;color:#cbd5e1}.error{color:#fca5a5}
.chart-wrap{position:relative;margin:0 0 10px;padding:12px;border:1px solid var(--line);border-radius:14px;background:rgb(17 24 39 / 88%)}.connection-chart{display:block;width:100%;height:240px;cursor:crosshair}.chart-tooltip{position:absolute;z-index:2;padding:6px 10px;border:1px solid #475569;border-radius:8px;background:rgb(15 23 42 / 94%);color:#e2e8f0;font-size:.78rem;line-height:1.35;pointer-events:none;white-space:nowrap;box-shadow:0 8px 24px rgb(0 0 0 / 28%)}.chart-range-label{margin:0 0 8px;color:var(--muted);font-size:.88rem}.chart-range{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 12px}.chart-range button{width:auto!important;min-height:34px!important;padding:6px 12px!important;border-color:#475569!important;background:#1e293b!important;box-shadow:none!important;font-size:.82rem!important}.chart-range button.active{border-color:#3b82f6!important;background:linear-gradient(135deg,#2563eb,#1d4ed8)!important;color:#fff!important}.chart-legend{display:flex;flex-wrap:wrap;gap:10px 18px;margin:0 0 24px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:rgb(15 23 42 / 72%);color:#dbe4f0;font-size:.88rem}.chart-legend-title{flex:1 0 100%;margin:0 0 2px;color:#93c5fd;font-size:.78rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase}.legend-item{display:inline-flex;align-items:center;gap:8px;white-space:nowrap}.legend-line{display:inline-block;width:28px;height:0;border-top:3px solid currentColor;border-radius:2px;vertical-align:middle}.legend-downlink .legend-line{color:#3b82f6}.legend-uplink .legend-line{color:#34d399}.legend-ping .legend-line{color:#fbbf24}
@media(max-width:900px){.app-shell{grid-template-columns:210px minmax(0,1fr)}.app-sidebar{padding:16px 10px}.main-nav>a{font-size:.84rem!important;padding:8px 10px!important}.app-main{padding:18px 14px 40px}.table-wrap,.app-main>table{overflow-x:auto}table{display:block;white-space:nowrap}}
@media(max-width:600px){.app-shell{grid-template-columns:176px minmax(0,1fr)}.main-nav .brand{font-size:.92rem!important}.main-nav .brand small{display:none}#internet-status{font-size:.72rem;padding:6px 8px}.chart-legend{flex-direction:column;gap:8px}.camera-name-row,.network-fields,.credentials-fields{align-items:stretch;flex-direction:column;gap:8px}.media-toggle-label{margin-top:0}h1{font-size:1.7rem}dialog{padding:20px!important}.actions{flex-wrap:wrap}.actions button{flex:1}.notice{right:12px!important;bottom:12px!important;left:12px;min-width:0!important}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important}}
`
